def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Extend diagonal pairs of matching non-background cells outward,
    # continuing only through background cells.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] != color:
                    continue
                for sr, sc in ((-dr, -dc), (dr, dc)):
                    ar, ac = (r, c) if (sr, sc) == (-dr, -dc) else (rr, cc)
                    nr, nc = ar + sr, ac + sc
                    while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg:
                        out[nr][nc] = color
                        nr += sr
                        nc += sc
    return out
